    /**
     * Tests getting all RateCards.
     *
     * @return    Collection
     */
    public List<RateCard> testGetAll() throws Throwable {
    LOGGER.info( "RateCardTest:testGetAll() - Retrieving Collection of RateCards:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all RateCard : " );
    List<RateCard> collection  = null;

    try {
        // call the static get method on the RateCardService
        collection = service.getAllRateCard();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            RateCard currEntity  = null;
            Iterator<RateCard> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getRateCardId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

